document.addEventListener('DOMContentLoaded',()=>{const prefersDark=localStorage.getItem('theme')==='dark';const html=document.documentElement;const icon=document.getElementById('theme-icon');const label=document.getElementById('theme-label');if(prefersDark){html.classList.add('dark');html.classList.remove('light');if(icon){icon.textContent='🌙';icon.style.textShadow='0 0 5px #00f0ff';}
const label=document.getElementById('theme-label');if(label)label.textContent='Modo Oscuro';}else{html.classList.add('light');html.classList.remove('dark');if(icon)icon.textContent='🌞';if(label)label.textContent='Modo Claro';}});function toggleDarkMode(){const html=document.documentElement;const icon=document.getElementById('theme-icon');const label=document.getElementById('theme-label');const isDark=!html.classList.contains('dark');html.classList.toggle('dark',isDark);html.classList.toggle('light',!isDark);localStorage.setItem('theme',isDark?'dark':'light');if(icon){icon.classList.add('rotate-180');setTimeout(()=>{icon.textContent=isDark?'🌙':'🌞';if(label){label.style.opacity=0;setTimeout(()=>{label.textContent=isDark?'Modo Oscuro':'Modo Claro';label.style.opacity=1;},250);}
icon.classList.remove('rotate-180');},250);}};